package com.marketplace.application.category;
import com.marketplace.application.shared.NotFoundException; import com.marketplace.domain.category.*; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Transactional public class CategoryApplicationService implements CategoryUseCase { private final CategoryRepository repo; public CategoryApplicationService(CategoryRepository repo){this.repo=repo;} public View create(Command c){return view(repo.save(Category.create(c.name(),c.description())));} public View update(Long id,Command c){var x=find(id);x.update(c.name(),c.description(),c.active());return view(repo.save(x));} @Transactional(readOnly=true) public View get(Long id){return view(find(id));} @Transactional(readOnly=true) public List<View> list(){return repo.findActive().stream().map(CategoryApplicationService::view).toList();} public void deactivate(Long id){var x=find(id);x.update(x.name(),x.description(),false);repo.save(x);} private Category find(Long id){return repo.findById(id).orElseThrow(()->new NotFoundException("Categoria",id));} private static View view(Category c){return new View(c.id(),c.name(),c.description(),c.active(),c.createdAt());} }
